def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    from collections import Counter
    bg = Counter(x for row in out for x in row).most_common(1)[0][0]
    # Extend each diagonal line indicated by two matching non-background cells.
    starts = [(r, c, out[r][c]) for r in range(h) for c in range(w) if out[r][c] != bg]
    for r, c, color in starts:
        for dr, dc in ((1, 1), (1, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and out[nr][nc] == color:
                y, x = r, c
                while 0 <= y - dr < h and 0 <= x - dc < w:
                    y -= dr
                    x -= dc
                    if out[y][x] == bg:
                        out[y][x] = color
                    elif out[y][x] != color:
                        break
                y, x = nr, nc
                while 0 <= y + dr < h and 0 <= x + dc < w:
                    y += dr
                    x += dc
                    if out[y][x] == bg:
                        out[y][x] = color
                    elif out[y][x] != color:
                        break
    return out


