from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    counts=Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    # Identify the sparse color and the boundary bars.
    bars=[]
    for r in (0,h-1):
        runs=[c for c in range(w) if grid[r][c]!=bg]
        if runs:
            color=grid[r][runs[0]]
            cols=[c for c in runs if grid[r][c]==color]
            bars.append((r,cols,color))
    marker=min((v for v in counts if v!=bg and all(v!=col for _,_,col in bars)),key=lambda v:counts[v])
    # The bars launch vertical copies of the marker color in their inward-facing
    # lane. Width matches the inner segment shown by the bar; markers become 4.
    for r,cols,color in bars:
        if r==0:
            beam=cols[-3:] if len(cols)>=3 else cols
            step=1
        else:
            beam=cols[-3:] if len(cols)>=3 else cols
            step=-1
        rr=r+step
        while 0<=rr<h:
            hit=[c for c in beam if grid[rr][c]==marker]
            if hit:
                for c in hit: out[rr][c]=4
                # Subsequent sparse markers on the same projected lane are also
                # converted to the collision color, while the fill stops at the first.
                for r2 in range(rr + step, h if step > 0 else -1, step):
                    for c in beam:
                        if grid[r2][c] == marker: out[r2][c] = 4
                break
            for c in beam:
                if grid[rr][c]==bg: out[rr][c]=marker
            rr+=step
    return out


