def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    colors = [v for v in freq if v != 0]
    marker = min(colors, key=lambda v: freq[v])
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0,c0 = min(r for r,c in pts), min(c for r,c in pts)
    shape = {(r-r0,c-c0) for r,c in pts}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            dest = [(r+dr,c+dc) for dr,dc in shape]
            if all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0 for rr,cc in dest):
                for rr,cc in dest: out[rr][cc] = marker
    return out

