 def transform(grid):
    h,w=len(grid),len(grid[0])
    sr=[r for r in range(h) if len(set(grid[r]))==1]
    sc=[c for c in range(w) if len({grid[r][c] for r in range(h)})==1]
    def spans(n,cuts):
        out=[]; start=0
        for x in cuts:
            if start<x: out.append((start,x))
            start=x+1
        if start<n: out.append((start,n))
        return out
    rs,cs=spans(h,sr),spans(w,sc)
    from collections import Counter
    count=Counter(grid[r][c] for a,b in rs for x,y in cs for r in range(a,b) for c in range(x,y))
    bg=count.most_common(1)[0][0]
    marker=min((v for v in count if v!=bg),key=lambda v:count[v])
    return [[1 if sum(grid[r][c]==marker for r in range(a,b) for c in range(x,y)) >= 2 else bg for x,y in cs] for a,b in rs]

