def transform(grid):
    """Copy the nonempty motif in each separated region into all regions of that size.

    Dividers are full uniform rows/columns between regions. A non-background
    color motif in any region marks the motif to repeat across the layout.
    """
    g = [r[:] for r in grid]
    h, w = len(g), len(g[0])
    if any(len(row) != w for row in g):
        raise ValueError("grid rows must have equal lengths")
    # In these layouts divider color is present as complete line and hence
    # separators are full uniform rows/columns. Ignore uniform stripes of
    # the panel background color; true separators carry another color.
    from collections import Counter
    # The panel background is the most frequent color in the input.
    global_counts = Counter(v for row in g for v in row)
    bg_guess = global_counts.most_common(1)[0][0]
    rd = [i for i, row in enumerate(g) if len(set(row)) == 1 and row[0] != bg_guess]
    cd = [j for j in range(w) if len({g[i][j] for i in range(h)}) == 1 and g[0][j] != bg_guess]
    rb, cb = [-1] + rd + [h], [-1] + cd + [w]
    regions = []
    for ri in range(len(rb)-1):
        for ci in range(len(cb)-1):
            top, bot = rb[ri]+1, rb[ri+1]
            left, right = cb[ci]+1, cb[ci+1]
            if top < bot and left < right:
                regions.append((top, bot, left, right))
    # Detect identical region geometry in a rectangular panel layout. The
    # marked motif in any occupied panel is copied to all same-sized panels.
    if not regions:
        return g
    sizes = {}
    for t,b,l,r in regions:
        sizes.setdefault((b-t,r-l), []).append((t,b,l,r))
    for (ph,pw), boxes in sizes.items():
        # Determine background from the most common color among cells of the
        # panels; exclude divider colors and treat the common color as empty.
        from collections import Counter
        divcolors = {g[i][0] for i in rd} | {g[0][j] for j in cd}
        cnt = Counter(g[y][x] for t,b,l,r in boxes for y in range(t,b) for x in range(l,r) if g[y][x] not in divcolors)
        if not cnt:
            continue
        bg = cnt.most_common(1)[0][0]
        occupied = []
        for t,b,l,r in boxes:
            patch = [row[l:r] for row in g[t:b]]
            if any(v != bg for row in patch for v in row):
                occupied.append((t,b,l,r,patch))
        if not occupied:
            continue
        # Use first marked panel as source and tile its sparse marks at the
        # same coordinates in each congruent panel, leaving background intact.
        seed = occupied[0][4]
        for t,b,l,r in boxes:
            for y in range(ph):
                for x in range(pw):
                    if seed[y][x] != bg:
                        g[t+y][l+x] = seed[y][x]
    return g

