def transform(grid):
    # Each fully colored horizontal row constrains a periodic row-color pattern.
    h, w = len(grid), len(grid[0])
    markers = {}
    for r, row in enumerate(grid):
        if all(v == row[0] for v in row) and row[0] != 0:
            markers[r] = row[0]
    for period in range(1, h + 1):
        seq = {}
        for r, color in markers.items():
            k = r % period
            if k in seq and seq[k] != color:
                break
            seq[k] = color
        else:
            # Fill any unconstrained residues by cyclic continuation from observed phases.
            for k in range(period):
                if k not in seq:
                    # nearest preceding constrained phase, wrapping around
                    prev = max((j for j in seq if j < k), default=None)
                    seq[k] = seq[prev] if prev is not None else seq[min(seq)]
            return [[seq[r % period] for _ in range(w)] for r in range(h)]
    return [row[:] for row in grid]


