from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    counts=Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    # Sparse marker color (the non-background color not forming edge bars).
    edge_colors=[]
    for line in (grid[0],grid[-1], [grid[r][0] for r in range(h)], [grid[r][-1] for r in range(h)]):
        edge_colors.extend(v for v in line if v!=bg)
    bar_color=Counter(edge_colors).most_common(1)[0][0]
    marker=min((v for v in counts if v not in (bg,bar_color)),key=lambda v:counts[v])
    # Markers are collision points, encoded as 4.
    points=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==marker]
    for r,c in points: out[r][c]=4
    # Each contiguous border bar projects its inward-facing width in the
    # perpendicular direction. The projected color is the sparse marker.
    # Edge bars can be horizontal or vertical.
    for r,line in ((0,grid[0]),(h-1,grid[-1])):
        cols=[c for c,v in enumerate(line) if v==bar_color]
        if cols:
            # Bars on the top/bottom edges project the rightmost half.
            width=(len(cols)+1)//2
            beam=cols[-width:]
            step=1 if r==0 else -1
            rr=r+step
            while 0<=rr<h:
                hit=[c for c in beam if grid[rr][c]==marker]
                if hit:
                    for c in hit: out[rr][c]=4
                    break
                for c in beam:
                    if grid[rr][c]==bg: out[rr][c]=marker
                rr+=step
    for c,line in ((0,[grid[r][0] for r in range(h)]),(w-1,[grid[r][-1] for r in range(h)])):
        rows=[r for r,v in enumerate(line) if v==bar_color]
        if len(rows) >= 2:
            # Only a genuine multi-cell bar on the side edge projects horizontally.
            beam=rows
            step=1 if c==0 else -1
            cc=c+step
            while 0<=cc<w:
                hit=[r for r in beam if grid[r][cc]==marker]
                if hit:
                    for r in hit: out[r][cc]=4
                    break
                for r in beam:
                    if grid[r][cc]==bg: out[r][cc]=marker
                cc+=step
    return out


