from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Split at uniform divider. At aligned panel positions, the shared palette
    # color is rendered as 3 when both panels contain it; otherwise render the
    # shared color as the background.
    sep_c = next((c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1), None)
    sep_r = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if sep_c is not None:
        a = [row[:sep_c] for row in grid]
        b = [row[sep_c+1:] for row in grid]
    elif sep_r is not None:
        a, b = grid[:sep_r], grid[sep_r+1:]
    else:
        raise ValueError('separator not found')
    common = set(v for row in a for v in row) & set(v for row in b for v in row)
    if not common:
        raise ValueError('no common palette color')
    # Common color used by corresponding cells; demos indicate a single such color.
    color = min(common, key=lambda x: sum(row.count(x) for row in a)+sum(row.count(x) for row in b))
    out = []
    for r, row in enumerate(a):
        out.append([3 if row[c] == color and b[r][c] == color else color for c in range(len(row))])
    return out

