def transform(grid):
    """Tile the grid with clockwise, counterclockwise, and half-turn rotations."""
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        raise ValueError("expected a nonempty square grid")
    a = [list(row) for row in grid]
    cw = [list(row) for row in zip(*a[::-1])]
    ccw = [list(row) for row in zip(*a)][::-1]
    half = [row[::-1] for row in a[::-1]]
    return [a[i] + cw[i] for i in range(n)] + [ccw[i] + half[i] for i in range(n)]

